import java.util.*;

public class Cutting {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        int b = scanner.nextInt();

        int[] arr = new int[n + 1];
        int[] evenCountArr = new int[n + 1];
        int[] oddCountArr = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            arr[i] = scanner.nextInt();
            if (arr[i] % 2 == 0) {
                evenCountArr[i] = evenCountArr[i - 1] + 1;
                oddCountArr[i] = oddCountArr[i - 1];
            } else {
                oddCountArr[i] = oddCountArr[i - 1] + 1;
                evenCountArr[i] = evenCountArr[i - 1];
            }
        }

        scanner.close();

        List<Integer> diffList = new ArrayList<>();
        for (int j = 2; j < n; j++) {
            int diff = Math.abs(arr[j] - arr[j + 1]);
            if (evenCountArr[j] == oddCountArr[j]) {
                diffList.add(diff);
            }
        }

        Collections.sort(diffList);

        int total = 0;
        for (int d : diffList) {
            if (b >= d) {
                b -= d;
                total++;
            } else {
                break;
            }
        }

        System.out.println(total);
    }
}
