#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    int n, b;
    std::cin >> n >> b;

    std::vector<int> arr(n + 1);
    std::vector<int> evenCountArr(n + 1, 0);
    std::vector<int> oddCountArr(n + 1, 0);

    for (int i = 1; i <= n; i++) {
        std::cin >> arr[i];
        if (arr[i] % 2 == 0) {
            evenCountArr[i] = evenCountArr[i - 1] + 1;
            oddCountArr[i] = oddCountArr[i - 1];
        } else {
            oddCountArr[i] = oddCountArr[i - 1] + 1;
            evenCountArr[i] = evenCountArr[i - 1];
        }
    }

    std::vector<int> diffList;
    for (int j = 2; j < n; j++) {
        int diff = std::abs(arr[j] - arr[j + 1]);
        if (evenCountArr[j] == oddCountArr[j]) {
            diffList.push_back(diff);
        }
    }

    std::sort(diffList.begin(), diffList.end());

    int total = 0;
    for (int d : diffList) {
        if (b >= d) {
            b -= d;
            total++;
        } else {
            break;
        }
    }

    std::cout << total << std::endl;

    return 0;
}
